@ResourceLock("SYSTEM_OUT")
class Stage6PerformanceTest {
    @Test
    void missedLatencyTargetIsReportedWithoutAbortingSubsequentMeasurements() {
        var output = new ByteArrayOutputStream();
        PrintStream previous = System.out;
        try (var captured = new PrintStream(output, true, StandardCharsets.UTF_8)) {
            System.setOut(captured);
            Stage6Performance.observe("listP95Millis", 501, 500);
            Stage6Performance.observe("ackP95Millis", 150, 150);
        } finally {
            System.setOut(previous);
        }
        String report = output.toString(StandardCharsets.UTF_8);
        assertTrue(report.contains("\"value\":501,\"target\":500,\"targetMet\":false,\"blocking\":false"));
        assertTrue(report.contains("\"value\":150,\"target\":150,\"targetMet\":true,\"blocking\":false"));
        assertEquals(2, report.lines().count());
    }

    @Test
    void invalidSamplesAndResourceLimitViolationsRemainFailures() {
        assertThrows(IllegalArgumentException.class, () -> Stage6Performance.observe("latency", -1, 500));
        assertThrows(IllegalArgumentException.class, () -> Stage6Performance.observe("latency", 1, -1));
        assertThrows(IllegalStateException.class, () -> Stage6Performance.metric("hostRssBytes", 101, 100));
    }
}

after.content:
try (var captured = new PrintStream(output, true, StandardCharsets.UTF_8)) {
    System.setOut(captured);
    assertThrows(Exception.class,
            () -> Stage6Performance.runResident(directory.resolve("missing"), 8_001));
} finally {
    System.setOut(previous);
}
